1	export interface Card {
2	  monster: string;
3	  rank?: number;
4	}
5	
6	const TYPE_THRESHOLD = 3;
7	const POINTS_PER_TYPE_BEYOND_THRESHOLD = 2;
8	const BASE_POINTS = 1;
9	
10	const isSphinx = (card: Card): boolean => card.monster === "sphinx";
11	
12	const countDistinctTypes = (army: Card[]): number =>
13	  new Set(army.map((card) => card.monster)).size;
14	
15	const pointsPerSphinx = (distinctTypes: number): number => {
16	  const typesBeyondThreshold = distinctTypes - TYPE_THRESHOLD;
17	  return typesBeyondThreshold > 0
18	    ? POINTS_PER_TYPE_BEYOND_THRESHOLD * typesBeyondThreshold
19	    : BASE_POINTS;
20	};
21	
22	export const scoreArmy = (army: Card[]): number =>
23	  army.filter(isSphinx).length * pointsPerSphinx(countDistinctTypes(army));
